import base64, json, os, re, shutil, sqlite3, sys, urllib.parse
def data(b):
    return json.loads(base64.b64decode(b))
def under(p, root):
    return p == root or p.startswith(root + "/")
def q(name):
    return '"' + name.replace('"', '""') + '"'
def moved(p):
    return TO + p[len(FROM):] if under(p, FROM) else None
def out(o):
    print(json.dumps(o))
    sys.exit(0)
def fail(why):
    print(why, file=sys.stderr)
    sys.exit(1)
def write(path, text):
    tmp = path + ".wsp-merge"
    with open(tmp, "w", encoding="utf-8", errors="surrogateescape", newline="") as f:
        f.write(text)
    if os.path.exists(path):
        shutil.copymode(path, tmp)
    os.replace(tmp, path)
FROM = data("Ii9yb290L3Ai")
TO = data("Ii9uZXcvcCI=")
merged = 0
kept = 0
notes = []
HOME = data("Ii9nLy5nZW1pbmki")
REG = data("Ii9nLy5nZW1pbmkvcHJvamVjdHMuanNvbiI=")
KEYS = data("W1siL3Jvb3QvcCIsIi9uZXcvcCIsInMiXSxbIi9yb290L3Avc3ViIiwiL25ldy9wL3N1YiIsInMyIl1d")
DIRS = data("WyJ0bXAiLCJoaXN0b3J5Il0=")
